// Credit project escrow
$.projectEscrow[projectId][token] += remaining;
proj.totalRewards += remaining;
proj.totalQuantity += quantity;
proj.availableSlots += quantity;
proj.status = ProjectStatus.Funded;

if (proj.status != ProjectStatus.Funded && proj.status != ProjectStatus.Active) {
    revert IQualityEngine.ProjectNotActive();
}

uint256 effectiveRep = inp.reputation < MIN_REPUTATION_FLOOR ? MIN_REPUTATION_FLOOR : inp.reputation;
uint256 sqrtStake = Math.sqrt(uint256(inp.stakeAmount));
uint256 w = sqrtStake * effectiveRep;
if (w == 0) w = 1;

function cancelExpiredCommitment(bytes32 projectId, uint256 index, address validator) public {
    // ...
    if (block.timestamp <= uint256(vc.commitTimestamp) + C.COMMIT_DEADLINE + C.REVEAL_DEADLINE) {
        revert IQualityEngine.ClaimDeadlineNotPassed();
    }

    uint128 committedStake = vc.stakedAmount;
    if (committedStake > 0) {
        $.vault.slashValidator(validator, committedStake);
    }

uint256 bondAmount = (contrib.rewardRate * uint256($.disputeBondBps)) / C.BPS;
if (bondAmount == 0) bondAmount = 1;
$.vault.lockContributor(msg.sender, bondAmount);

if (dispute.status != DisputeStatus.Upheld) {
    $.vault.unlockContributor(dispute.challenger, dispute.bondAmount);
}

if (result.weightedAverage >= proj.consensusThreshold) {
    // Accepted — mark computed only on acceptance
    report.computed = true;
    newStatus = ContributionStatus.Accepted;
    contrib.status = ContributionStatus.Accepted;
    contrib.challengeEndsAt = uint64(block.timestamp + C.CHALLENGE_PERIOD);
    ReputationLib.update(contrib.contributor, C.CONTRIBUTOR_ROLE_KEY, true, qualityBonus);

// Deduct protocol fee (based on actual received, not requested amount)
uint256 protocolFee = (received * $.protocolFeeBps) / C.BPS;
if (protocolFee > 0) {
    IERC20(token).safeTransfer($.treasury, protocolFee);
}
remaining = received - protocolFee;

// Deduct origination adapter fee
if (adapter != address(0) && $.originationFeeBps > 0) {
    uint256 originationFee = (remaining * $.originationFeeBps) / C.BPS;
    $.pendingRewards[adapter][token] += originationFee;
    $.originationAdapter[projectId] = adapter;
    remaining -= originationFee;
}

if (adapter != address(0) && $.contributionFeeBps > 0) {
    uint256 fee = (reward * $.contributionFeeBps) / C.BPS;
    $.pendingRewards[adapter][token] += fee;
    reward -= fee;
    emit IQualityEngine.ContributionAdapterFeePaid(projectId, index, adapter, fee);
}

function setValidatorCapacity(uint256 amount) public {
    _getStorage().vault.lockValidatorCapacity(msg.sender, amount);
}

if (totalAccWeight > 0 && weight > 0) {
    uint256 reward = (proj.totalRewards * uint256(proj.validatorRewardBps) * weight)
        / (C.BPS * proj.totalQuantity * totalAccWeight);
    $.pendingRewards[msg.sender][proj.rewardToken] += reward;
    $.projectEscrow[projectId][proj.rewardToken] -= reward;
}

{ // Lock originator stake if required
    uint256 originatorStakeReq = $.originatorStakeRequirement;
    if (originatorStakeReq > 0) {
        uint256 stakeNeeded = originatorStakeReq * quantity;
        $.vault.lockContributor(msg.sender, stakeNeeded);
        $.originatorLockedStake[projectId] += stakeNeeded;
    }
}

// Lock stake from validator capacity to in-flight
if (stakeAmount > 0) {
    $.vault.commitStake(msg.sender, stakeAmount);
}

if (outlier) {
    uint256 slashAmt = uint256(vcr.slashAmount);
    if (slashAmt > 0 && committedStake > 0) {
        uint256 actualSlash = slashAmt > committedStake ? committedStake : slashAmt;
        $.vault.slashValidator(msg.sender, actualSlash);
        uint256 remaining = committedStake - actualSlash;
        if (remaining > 0) {
            $.vault.releaseCommit(msg.sender, remaining);
        }
    }

function claimReward(address token) public {
    EngineStorage storage $ = _getStorage();
    uint256 amount = $.pendingRewards[msg.sender][token];
    if (amount == 0) revert IQualityEngine.NoRewardToClaim();
    $.pendingRewards[msg.sender][token] = 0;
    IERC20(token).safeTransfer(msg.sender, amount);
    emit IQualityEngine.RewardClaimed(msg.sender, token, amount);
}
